using Microsoft.AspNetCore.Mvc; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.UseCases; using OrcaFacil.Domain.Enums;
namespace OrcaFacil.Api.Controllers; [ApiController,Route("api/documents")]
public class DocumentsController(DocumentService docs,IDocumentQueries queries,IPdfService pdf):ControllerBase{ [HttpGet] public Task<IReadOnlyList<DocumentSummaryDto>> List(CancellationToken ct)=>queries.ListDocumentsAsync(Guid.Parse(User.FindFirst("sub")?.Value ?? Guid.Empty.ToString()),ct); [HttpPost("budget")] public Task<OrcaFacil.Shared.Result<Guid>> Budget(CreateDocumentCommand c,CancellationToken ct)=>docs.CreateAsync(c with { Type=DocumentType.Budget},ct); [HttpPost("receipt")] public Task<OrcaFacil.Shared.Result<Guid>> Receipt(CreateDocumentCommand c,CancellationToken ct)=>docs.CreateAsync(c with { Type=DocumentType.Receipt},ct); [HttpPost("{id:guid}/public-link")] public Task<OrcaFacil.Shared.Result<string>> Link(Guid id,CancellationToken ct)=>docs.GeneratePublicLinkAsync(Guid.Parse(User.FindFirst("sub")?.Value ?? Guid.Empty.ToString()),id,ct); }
